    def assign_breaks(self) -> dict[str, dict[datetime, int]]:
        """SOW 2.3 on the current shifts. Returns agents on break per queue per interval."""
        rule = self.cfg["break"]
        length = timedelta(minutes=rule["minutes"])
        lo, hi = (timedelta(hours=h) for h in rule["window_hours"])
        taken = {q: defaultdict(int) for q in self.queues}
