    def hours(self) -> float:
        return sum(_elapsed_hours(sh.segments) for sh in self.shifts)


def required_hours(req: pd.DataFrame, cfg: dict) -> float:
    return float(req["required"].sum()) * cfg["interval_minutes"] / 60.0


def _score(short: dict) -> tuple[int, int]:
    return (sum(len(v) for v in short.values()), sum(d for v in short.values() for _, d in v))


def schedule_week(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> list[Shift]:
    plan = _Plan(req, cfg, agents, week)
    for day in plan.days:
        plan.fill_day(day)
    budget = float(cfg.get("efficiency_bound", 1e9)) * required_hours(req, cfg) - 0.05
    _repair(plan, budget)
    plan.assign_breaks()
    return plan.shifts


def _repair(plan: _Plan, budget: float) -> None:
    """Add shifts until every operating interval is met net of breaks, or nothing helps / fits."""
    taken = plan.assign_breaks()
    short = plan.shortfall(taken)
    score = _score(short)
    while score[0]:
        # work on the deepest shortfall (earliest on ties), across queues
        q, (t, _) = max(((q, x) for q, v in short.items() for x in v),
                        key=lambda p: (p[1][1], -p[1][0].timestamp(), p[0]))
        day = t.astimezone(plan.z).date()
        best = None
        tried: set[tuple[str, str]] = set()
        for tpl in plan.templates:
            segs = tpl.segments_utc(day, plan.tz)
            ivs = _covered(segs, plan.day_grid[day])
            if t not in ivs or plan.hours() + _elapsed_hours(segs) > budget:
                continue
            for qq in plan.queues:
                if qq != q:
                    continue
                a = plan.pick_agent(qq, tpl, day, segs)
                if a is None or (tpl.id, qq) in tried:
                    continue
                tried.add((tpl.id, qq))
                sh = plan.add(a, qq, tpl, day, segs, ivs)
                s2 = _score(plan.shortfall(plan.assign_breaks()))
                plan.remove(sh)
                key = (s2, _elapsed_hours(segs), tpl.id)
                if s2 < score and (best is None or key < best[0]):
                    best = (key, a, qq, tpl, segs, ivs)
        if best is None:
            # nothing helps this interval: leave it, and look at the next-worst one
            short = {k: [x for x in v if not (k == q and x[0] == t)] for k, v in short.items()}
            score = _score(short)
            plan_blocked = True
            if not any(short.values()):
                break
            continue
        _, a, qq, tpl, segs, ivs = best
        plan.add(a, qq, tpl, day, segs, ivs)
        taken = plan.assign_breaks()
        short = plan.shortfall(taken)
        score = _score(short)

